'use strict';
const $=s=>document.querySelector(s),canvas=$('#map'),ctx=canvas.getContext('2d');let data=FpsLevel.load(localStorage),level=0,tool="select",painting=false,lastCell='',history=[],moving=null,drag=null;
let view={x:-2,z:-2,size:32},pan=null,lastPointer=null;
const colors=['#141e28','#895a35','#236ea6','#a27038','#286e60'];
for(let n=0;n<7;n++){const o=document.createElement('option');o.value=n;o.textContent='Étage '+(n+1);$('#floor').append(o);}
function message(text,error=false){$('#status').textContent=text;$('#status').style.color=error?'#ff9999':'#9fffd0';}
function checkpoint(){history.push(JSON.stringify({data,view}));if(history.length>50)history.shift();}
function draw(){canvas.width=920;canvas.height=760;const map=data.maps[level],size=view.size;ctx.fillStyle='#101a24';ctx.fillRect(0,0,920,760);ctx.font='bold 10px monospace';ctx.textAlign='center';const tile=(x,z,color)=>{const px=(x-view.x)*size,pz=(z-view.z)*size;ctx.fillStyle=color;ctx.fillRect(px,pz,size,size);ctx.strokeStyle='#34424e';ctx.strokeRect(px+.5,pz+.5,size-1,size-1);};for(let z=Math.floor(view.z);z<view.z+760/size;z++)for(let x=Math.floor(view.x);x<view.x+920/size;x++)tile(x,z,colors[map[z]?.[x]??0]);for(const p of FpsLevel.protectedCells(level,data))tile(p.x,p.z,'rgba(255,227,111,.13)');for(const p of FpsLevel.points(level,data)){const x=(p.x-view.x)*size,z=(p.z-view.z)*size;ctx.strokeStyle='#ffe36f';ctx.lineWidth=2;ctx.strokeRect(x+2,z+2,size-4,size-4);ctx.fillStyle='#ffe36f';ctx.fillText(p.label,x+size/2,z+size/2);ctx.lineWidth=1;}if(drag){for(const cell of drag.cells){tile(cell.x+drag.dx,cell.z+drag.dz,dragValid()?'#8dffbb88':'#ff777788');}}}
function cellAt(e){const r=canvas.getBoundingClientRect();return {x:Math.floor(view.x+(e.clientX-r.left)*920/r.width/view.size),z:Math.floor(view.z+(e.clientY-r.top)*760/r.height/view.size)};}
function paintStroke(e){if(lastPointer&&!moving){const r=canvas.getBoundingClientRect(),steps=Math.max(1,Math.ceil(Math.hypot(e.clientX-lastPointer.clientX,e.clientY-lastPointer.clientY)/(view.size*r.width/920*.4)));for(let i=1;i<=steps;i++)paint({clientX:lastPointer.clientX+(e.clientX-lastPointer.clientX)*i/steps,clientY:lastPointer.clientY+(e.clientY-lastPointer.clientY)*i/steps});}else paint(e);lastPointer={clientX:e.clientX,clientY:e.clientY};}
function grow(x,z){const shift=FpsLevel.expand(data,x,z);view.x+=shift.x;view.z+=shift.z;return shift;}
function paint(e){let {x,z}=cellAt(e);const key=x+','+z;if(key===lastCell)return;lastCell=key;if(moving){moveAccess(x,z);return;}if(tool===0&&!data.maps[level][z]?.[x])return;const shift=grow(x,z);x+=shift.x;z+=shift.z;if(FpsLevel.protectedCells(level,data).some(p=>p.x===x&&p.z===z)){message('Les accès sont protégés.',true);return;}data.maps[level][z][x]=tool;draw();}
function dragValid(){if(!drag)return false;if(drag.access){try{FpsLevel.moveAccess(data,drag.access,drag.start.x+drag.dx,drag.start.z+drag.dz);return true;}catch{return false;}}const map=data.maps[level],source=new Set(drag.cells.map(c=>c.x+','+c.z)),protectedSet=new Set(FpsLevel.protectedCells(level,data).map(c=>c.x+','+c.z));return drag.cells.every(c=>{const x=c.x+drag.dx,z=c.z+drag.dz;return !protectedSet.has(x+','+z)&&((map[z]?.[x]??0)===0||source.has(x+','+z));});}
canvas.onpointerdown=e=>{e.preventDefault();canvas.focus({preventScroll:true});canvas.setPointerCapture(e.pointerId);if(tool==='pan'||e.button===1){pan={x:e.clientX,z:e.clientY,view:{...view}};return;}if(tool==='select'&&!moving){const start=cellAt(e),map=data.maps[level],type=map[start.z]?.[start.x],access=FpsLevel.points(level,data).find(p=>p.x===start.x&&p.z===start.z);if(access){drag={start,cells:[start],access,type:0,dx:0,dz:0};$('#access').value=String(FpsLevel.points(level,data).findIndex(p=>p.id===access.id&&p.index===access.index));accessType();draw();return;}if(!type||false)return;const cells=[start],seen=new Set([start.x+','+start.z]);if(type>=2)for(let i=0;i<cells.length;i++)for(const [dx,dz] of [[1,0],[-1,0],[0,1],[0,-1]]){const x=cells[i].x+dx,z=cells[i].z+dz,key=x+','+z;if(map[z]?.[x]===type&&!seen.has(key)){seen.add(key);cells.push({x,z});}}drag={start,cells,type,dx:0,dz:0};draw();return;}checkpoint();painting=true;lastCell='';lastPointer=null;paintStroke(e);};
canvas.onpointermove=e=>{if(pan){const r=canvas.getBoundingClientRect();view.x=pan.view.x-(e.clientX-pan.x)*920/r.width/view.size;view.z=pan.view.z-(e.clientY-pan.z)*760/r.height/view.size;draw();return;}if(drag){const cell=cellAt(e);drag.dx=cell.x-drag.start.x;drag.dz=cell.z-drag.start.z;draw();}else if(painting)paintStroke(e);};
canvas.onpointerup=e=>{if(pan){pan=null;return;}if(drag){const cell=cellAt(e);drag.dx=cell.x-drag.start.x;drag.dz=cell.z-drag.start.z;if(drag.dx||drag.dz){if(dragValid()){checkpoint();if(drag.access){const x=drag.start.x+drag.dx,z=drag.start.z+drag.dz;data=FpsLevel.moveAccess(data,drag.access,x,z);const target=drag.access.id==='stairs'?data.structure.stairs[drag.access.index]:data.structure[drag.access.id];view.x+=target.x-x;view.z+=target.z-z;controls();message('Accès déplacé. Ctrl+Z pour annuler.');}else{const shift=grow(Math.min(...drag.cells.map(c=>c.x+drag.dx)),Math.min(...drag.cells.map(c=>c.z+drag.dz)));grow(Math.max(...drag.cells.map(c=>c.x+drag.dx+shift.x)),Math.max(...drag.cells.map(c=>c.z+drag.dz+shift.z)));const map=data.maps[level];for(const c of drag.cells)map[c.z+shift.z][c.x+shift.x]=0;for(const c of drag.cells)map[c.z+drag.dz+shift.z][c.x+drag.dx+shift.x]=drag.type;message('Bloc déplacé. Ctrl+Z pour annuler.');}}else message('Déplacement impossible : case occupée, bord ou accès protégé.',true);}drag=null;draw();}painting=false;};
canvas.onpointercancel=()=>{painting=false;drag=null;pan=null;draw();};
document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{tool=['select','pan'].includes(b.dataset.tool)?b.dataset.tool:Number(b.dataset.tool);moving=null;drag=null;painting=false;draw();document.querySelectorAll('[data-tool]').forEach(t=>t.setAttribute('aria-pressed',String(t===b)));});$('#floor').onchange=()=>{level=Number($('#floor').value);moving=null;drag=null;painting=false;controls();draw();};
function controls(){const selected=$('#access').value||'0';const map=data.maps[level];$("#access").replaceChildren(...FpsLevel.points(level,data).map((p,i)=>{const o=document.createElement("option");o.value=i;o.textContent=p.label+' · '+(FpsLevel.surface(p)==='ceiling'?'plafond':'mur');return o;}));$("#access").value=String(Math.min(Number(selected),$("#access").options.length-1));accessType();}
function undo(){if(history.length){const previous=JSON.parse(history.pop());data=previous.data;view=previous.view;moving=null;drag=null;painting=false;controls();draw();message('Modification annulée.');}}$('#undo').onclick=undo;document.addEventListener('keydown',e=>{if(e.ctrlKey&&e.key.toLowerCase()==='z'&&!(e.target instanceof HTMLInputElement)){e.preventDefault();undo();}});
$('#reset-floor').onclick=()=>{checkpoint();const map=data.maps[level];data.maps[level]=map.map((row,z)=>row.map((v,x)=>x===0||z===0||x===row.length-1||z===map.length-1?1:0));draw();message('Étage réinitialisé. Appliquez pour modifier le jeu.');};
function apply(){try{data=FpsLevel.validate(data);localStorage.setItem(FpsLevel.KEY,JSON.stringify(data));message('Niveau appliqué. Rechargez le jeu pour le charger.');return true;}catch(e){message(e.message,true);return false;}}
$('#apply').onclick=apply;$('#test').onclick=()=>{if(apply())window.open('./?fps-test=true&fps-floor='+level,'_blank','noopener');};
$('#export').onclick=()=>{try{const value=FpsLevel.validate(data),url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='minitman-fps-level.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){message(e.message,true);}};
$('#import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;const imported=FpsLevel.validate(JSON.parse(await file.text()));checkpoint();data=imported;controls();draw();message('Niveau importé. Cliquez sur Appliquer au jeu.');}catch(e){message(e.message,true);}e.target.value='';};controls();draw();

$('#move-access').onclick=()=>{moving=FpsLevel.points(level,data)[Number($('#access').value)];message('Cliquez dans la grille pour déplacer : '+moving.label);};
function moveAccess(x,z){try{data=FpsLevel.moveAccess(data,moving,x,z);const target=moving.id==='stairs'?data.structure.stairs[moving.index]:data.structure[moving.id];view.x+=target.x-x;view.z+=target.z-z;moving=null;painting=false;controls();draw();message('Accès déplacé. Appliquez pour enregistrer.');}catch(e){message(e.message,true);}}
$('#center').onclick=()=>{const p=FpsLevel.points(level,data)[0];view.x=p.x-5;view.z=p.z-5;draw();};
canvas.addEventListener('wheel',e=>{e.preventDefault();const r=canvas.getBoundingClientRect(),px=(e.clientX-r.left)*920/r.width,pz=(e.clientY-r.top)*760/r.height,x=view.x+px/view.size,z=view.z+pz/view.size;view.size=Math.max(12,Math.min(64,view.size*(e.deltaY<0?1.15:1/1.15)));view.x=x-px/view.size;view.z=z-pz/view.size;draw();},{passive:false});
function accessType(){const point=FpsLevel.points(level,data)[Number($('#access').value)||0];$('#surface').value=FpsLevel.surface(point);$('#surface').disabled=point.id==='stairs';}
$('#access').onchange=accessType;
$('#surface').onchange=()=>{checkpoint();const point=FpsLevel.points(level,data)[Number($('#access').value)||0],target=point.id==='stairs'?data.structure.stairs[point.index]:data.structure[point.id];target.surface=$('#surface').value;controls();draw();message('Type d’accès modifié.');};

